arguments.new_str:
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train model at startup
var trainer = new TicketModelTrainer(builder.Environment.ContentRootPath);
trainer.Train();

builder.Services.AddSingleton(trainer);

// Use pooled prediction engine (thread-safe for ASP.NET Core)
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(trainer.ModelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

arguments.old_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Register trainer as singleton so metrics persist
builder.Services.AddSingleton<TicketModelTrainer>();

// Train the model during startup to produce the .zip file
using (var tempProvider = builder.Services.BuildServiceProvider())
{
    var trainer = tempProvider.GetRequiredService<TicketModelTrainer>();
    trainer.Train();
}

// Register prediction engine pool from the trained model file
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

// Re-train with the real singleton so metrics are available via DI
var trainerInstance = app.Services.GetRequiredService<TicketModelTrainer>();
trainerInstance.Train();

app.MapControllers();
app.Run();

