using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelTrainer
{
    private readonly string _dataPath;
    private readonly string _modelPath;
    private MulticlassClassificationMetrics? _metrics;

    public MulticlassClassificationMetrics? Metrics => _metrics;
    public string ModelPath => _modelPath;

    public TicketModelTrainer(string contentRootPath)
    {
        _dataPath = Path.Combine(contentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(contentRootPath, "Data", "model.zip");
    }

    public void Train()
    {
        var mlContext = new MLContext(seed: 42);

        var data = mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // Evaluate with train/test split
        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.3, seed: 42);
        var evalModel = pipeline.Fit(split.TrainSet);
        var predictions = evalModel.Transform(split.TestSet);
        _metrics = mlContext.MulticlassClassification.Evaluate(predictions);

        // Train final model on all data
        var fullModel = pipeline.Fit(data);
        mlContext.Model.Save(fullModel, data.Schema, _modelPath);
    }
}

